args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?p ?mother ?motherLabel WHERE {
  <http://dbpedia.org/resource/Maria_of_J%C3%BClich-Berg> ?p ?mother .
  FILTER(regex(str(?p), "mother|parent", "i"))
  OPTIONAL { ?mother rdfs:label ?motherLabel FILTER(lang(?motherLabel) = 'en') }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?pp ?mother ?motherLabel WHERE {
  ?mother ?pp <http://dbpedia.org/resource/Maria_of_J%C3%BClich-Berg> .
  FILTER(regex(str(?pp), "child|children|issue|offspring", "i"))
  OPTIONAL { ?mother rdfs:label ?motherLabel FILTER(lang(?motherLabel) = 'en') }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
